svg.script:

(function() {
  var root = document.querySelector('.fm1p8-root');
  if (!root) return;

  // TIME CONTROLLER LOGIC
  var timeBtns = root.querySelectorAll('[data-time-set]');
  timeBtns.forEach(function(btn) {
    btn.addEventListener('click', function(e) {
      var tVal = btn.getAttribute('data-time-set');
      root.setAttribute('data-time', tVal);
    });
    btn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        var tVal = btn.getAttribute('data-time-set');
        root.setAttribute('data-time', tVal);
      }
    });
  });

  // TOOLTIP ENGINE
  var tooltip = root.querySelector('#fm1p8-tooltip-el');
  var ttTitle = root.querySelector('#fm1p8-tt-title');
  var ttDesc = root.querySelector('#fm1p8-tt-desc');
  var hotspots = root.querySelectorAll('.fm1p8-hotspot');

  function showTooltip(evt, el) {
    var title = el.getAttribute('data-title') || '';
    var desc = el.getAttribute('data-desc') || '';
    if (!title) return;

    ttTitle.textContent = title;
    ttDesc.textContent = desc;

    var ctm = root.getScreenCTM();
    if (!ctm) return;

    var pt = root.createSVGPoint();
    pt.x = evt.clientX || (evt.touches && evt.touches[0].clientX) || 0;
    pt.y = evt.clientY || (evt.touches && evt.touches[0].clientY) || 0;
    var svgPt = pt.matrixTransform(ctm.inverse());

    var x = svgPt.x + 12;
    var y = svgPt.y + 12;

    if (x + 220 > 940) x = svgPt.x - 230;
    if (y + 54 > 620) y = svgPt.y - 60;

    tooltip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    tooltip.style.opacity = '1';
  }

  function hideTooltip() {
    tooltip.style.opacity = '0';
  }

  hotspots.forEach(function(hs) {
    hs.addEventListener('mousemove', function(e) { showTooltip(e, hs); });
    hs.addEventListener('mouseenter', function(e) { showTooltip(e, hs); });
    hs.addEventListener('mouseleave', hideTooltip);
    hs.addEventListener('focus', function(e) { showTooltip(e, hs); });
    hs.addEventListener('blur', hideTooltip);
  });
})();
